'use strict';

/* Browser-local matrix parsing, descriptive QC and exports. */
const dataState={version:0,matrix:null,qc:null,staged:null,source:null,abort:null,pending:false,page:1};
const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const percent=v=>Number.isFinite(v)?(v*100).toFixed(2)+'%':'—';
const numberText=v=>v===null||!Number.isFinite(v)?'—':Number(v).toFixed(4);
function setPending(value){dataState.pending=value;$('cancelImport').hidden=!value;$('confirmImport').disabled=value;$('save').disabled=value||busy;const q=dataState.qc,m=dataState.matrix;$('run').disabled=value||busy||!m?.phenotypeAvailable||!q?.keptSamples.length||!q?.keptVariants.length||!q?.cases||!q?.controls;document.querySelectorAll('#mappingPanel input,#mappingPanel select').forEach(e=>e.disabled=value);}
function resetFlow(){$('progress').style.width='0%';$('flowState').textContent='待运行';document.querySelectorAll('.flow-item').forEach(e=>e.classList.remove('done','running'));$('status').textContent='真实描述性质控已就绪；模型训练与关联分析仍为演示。';}
function startJob(){dataState.abort?.abort();dataState.abort=new AbortController();return{version:++dataState.version,signal:dataState.abort.signal};}
function isCurrent(job){return job.version===dataState.version&&!job.signal.aborted;}
function emptyMatrix(){dataState.matrix=null;dataState.qc=null;dataState.source=null;dataState.page=1;uploaded=false;$('matrixPanel').classList.add('hidden');$('matrixEmpty').classList.remove('hidden');$('sampleCount').innerHTML='— <small>samples</small>';$('snpCount').innerHTML='— <small>variants</small>';$('sampleMeta').textContent='未导入有效矩阵';$('snpMeta').textContent='未导入有效矩阵';resetFlow();$('status').textContent='选择矩阵并确认字段，或加载示例。';}
function clearInput(message='已清除输入'){if(busy){toast('请等待演示结束后清除。');return;}startJob();dataState.staged=null;$('mappingPanel').classList.add('hidden');$('importIssues').replaceChildren();emptyMatrix();$('filename').textContent='尚未选择文件';$('fileInfo').textContent='文件仅在本地处理';$('fileError').textContent='';setPending(false);if(message)toast(message);}
$('clearInput').onclick=()=>clearInput();$('discardImport').onclick=()=>clearInput('已取消本次文件');$('cancelImport').onclick=()=>clearInput('导入已取消');
async function matrixTask(action,payload,signal){
  const main=()=>action==='parse'?SNPMatrix.parse(payload.text,{...payload.options,signal}):action==='build'?SNPMatrix.build(payload.parsed,{...payload.options,signal}):SNPMatrix.qc(payload.matrix,payload.config,{signal});
  if(location.protocol==='file:'||typeof Worker==='undefined')return main();
  return new Promise((resolve,reject)=>{let worker;try{worker=new Worker('matrix-worker.js');}catch{return resolve(main());}let done=false;const finish=(fn,result)=>{if(done)return;done=true;signal?.removeEventListener('abort',abort);worker.terminate();fn(result);};const abort=()=>finish(reject,new DOMException('导入已取消','AbortError'));if(signal?.aborted){abort();return;}signal?.addEventListener('abort',abort,{once:true});worker.onmessage=e=>{const m=e.data;if(m.type==='done')finish(resolve,m.result);else if(m.type==='error')finish(reject,new SNPMatrix.MatrixError(m.message,m.issues));};worker.onerror=()=>finish(resolve,main());try{worker.postMessage({action,payload});}catch{finish(resolve,main());}});
}
function showImportError(error){$('fileError').textContent=error.message;$('fileInfo').textContent='导入失败，尚无有效矩阵';const issues=error.issues||[];$('importIssues').innerHTML=issues.length?'<div class="table-wrap error-list"><table><thead><tr><th>文件行</th><th>字段</th><th>错误</th></tr></thead><tbody>'+issues.map(i=>`<tr><td>${i.line}</td><td>${escapeHTML(i.column)}</td><td>${escapeHTML(i.message)}</td></tr>`).join('')+'</tbody></table></div>':'';toast(error.message);}
function refreshExcluded(){if(!dataState.staged)return;const chosen=new Set([...$('excludedColumns').selectedOptions].map(o=>o.value)),id=+$('idColumn').value,ph=$('phenotypeColumn').value===''?-1:+$('phenotypeColumn').value;$('excludedColumns').innerHTML=dataState.staged.parsed.header.map((name,i)=>i===id||i===ph?'':`<option value="${i}" ${chosen.has(String(i))?'selected':''}>${escapeHTML(name)}</option>`).join('');}
$('idColumn').onchange=refreshExcluded;$('phenotypeColumn').onchange=refreshExcluded;
function setupMapping(){const{header,records,delimiter}=dataState.staged.parsed,options=header.map((name,i)=>`<option value="${i}">${escapeHTML(name)}</option>`).join('');$('idColumn').innerHTML=options;$('phenotypeColumn').innerHTML='<option value="">不使用表型（仅描述性质控）</option>'+options;const norm=h=>h.trim().toLowerCase(),id=header.findIndex(h=>['sample_id','sample','iid','id'].includes(norm(h))),ph=header.findIndex(h=>['phenotype','pheno','pheno1','label'].includes(norm(h)));$('idColumn').value=String(id<0?0:id);$('phenotypeColumn').value=String(ph);$('genotypeMode').value='hardcall';$('phenotypeMode').value='01';const notes=[];if(ph>=0){const vals=new Set(records.map(r=>r.values[ph]));if(vals.size&&[...vals].every(v=>v==='1'||v==='2')&&vals.has('1')&&vals.has('2')){$('phenotypeMode').value='12';notes.push('检测到 1/2 表型，已预选 1=对照、2=病例；请核对研究编码。');}}let fractional=false;for(const r of records.slice(0,200)){for(let j=0;j<header.length;j++){if(j===(id<0?0:id)||j===ph)continue;const v=r.values[j];if(v&&Number.isFinite(Number(v))&&!Number.isInteger(Number(v))){fractional=true;break;}}if(fractional)break;}if(fractional){$('genotypeMode').value='dosage';notes.push('检测到小数基因型，已预选 0–2 剂量编码；请确认是二倍体剂量。');}if(records.some(r=>r.values.some(v=>v.trim()==='-9'))){$('missingTokens').value='NA,NaN,.,-9';notes.push('检测到 -9，已加入缺失值标记。');}$('excludedColumns').innerHTML='';refreshExcluded();$('stagedInfo').textContent=`解析到 ${records.length} 行样本、${header.length} 列；分隔符为 ${{',':'逗号','\t':'制表符',';':'分号',whitespace:'空白'}[delimiter]}。样本 ID 和 SNP 列将用于矩阵；确认后开始校验。${notes.length?' '+notes.join(' '):''}`;$('mappingPanel').classList.remove('hidden');$('importIssues').replaceChildren();}
async function inputFile(file,autoConfirm=false){
  if(!file)return;if(busy){toast('请等待演示流程完成后导入。');return;}const job=startJob();emptyMatrix();dataState.staged=null;$('mappingPanel').classList.add('hidden');$('importIssues').replaceChildren();$('fileError').textContent='';$('filename').textContent=file.name;$('fileInfo').textContent='正在读取并解析…';setPending(true);
  try{if(!/\.(csv|tsv|txt|raw)$/i.test(file.name))throw new SNPMatrix.MatrixError('请选择 UTF-8 CSV、TSV、TXT 或文本格式 PLINK .raw 矩阵；VCF / BCF / BED / PGEN 等需先转换。');if(file.size>SNPMatrix.LIMITS.bytes)throw new SNPMatrix.MatrixError('文件超过 10 MB；请拆分矩阵，或用 PLINK 过滤样本和位点后再导入。');const bytes=new Uint8Array(await file.arrayBuffer());if(!isCurrent(job))return;if((bytes[0]===255&&bytes[1]===254)||(bytes[0]===254&&bytes[1]===255))throw new SNPMatrix.MatrixError('检测到 UTF-16 文件，请另存为 UTF-8 CSV / TSV。');let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch{throw new SNPMatrix.MatrixError('文件不是有效 UTF-8，请转换编码后重试。');}const delimiter=$('delimiter').value==='tab'?'\t':$('delimiter').value,parsed=await matrixTask('parse',{text,options:{delimiter:autoConfirm?'auto':delimiter}},job.signal);if(!isCurrent(job))return;dataState.staged={parsed,file:{name:file.name,size:file.size,lastModified:file.lastModified||null},example:autoConfirm};setupMapping();$('fileInfo').textContent='已解析，等待字段与编码确认';if(!autoConfirm)navigate('data');}
  catch(error){if(isCurrent(job)&&error.name!=='AbortError'){showImportError(error);navigate('data');}}
  finally{if(isCurrent(job)){setPending(false);$('file').value='';}}
  if(autoConfirm&&isCurrent(job)&&dataState.staged){$('genotypeMode').value='hardcall';$('phenotypeMode').value='01';$('missingTokens').value='NA,NaN,.';await confirmImport();}
}
async function confirmImport(){if(!dataState.staged||dataState.pending||busy)return;const staged=dataState.staged,job=startJob();setPending(true);$('fileError').textContent='';$('importIssues').replaceChildren();$('fileInfo').textContent='正在校验基因型并计算质控…';try{const options={idColumn:+$('idColumn').value,phenotypeColumn:$('phenotypeColumn').value,excluded:[...$('excludedColumns').selectedOptions].map(o=>+o.value),genotypeMode:$('genotypeMode').value,phenotypeMode:$('phenotypeMode').value,missingTokens:$('missingTokens').value.split(',').map(x=>x.trim()).filter(Boolean)},matrix=await matrixTask('build',{parsed:staged.parsed,options},job.signal);if(!isCurrent(job))return;const qc=await matrixTask('qc',{matrix,config},job.signal);if(!isCurrent(job))return;dataState.matrix=matrix;dataState.qc=qc;dataState.source={...staged.file,example:staged.example,importedAt:new Date().toISOString()};dataState.staged=null;dataState.page=1;uploaded=true;$('mappingPanel').classList.add('hidden');renderMatrix();resetFlow();toast(matrix.phenotypeAvailable?'矩阵已导入；描述性质控已计算。':'矩阵已导入为仅质控模式；模型演示需提供完整病例/对照表型。');}catch(error){if(isCurrent(job)&&error.name!=='AbortError')showImportError(error);}finally{if(isCurrent(job))setPending(false);}}
$('confirmImport').onclick=confirmImport;$('file').onchange=e=>inputFile(e.target.files[0]);
const drop=$('drop');['dragenter','dragover'].forEach(t=>drop.addEventListener(t,e=>{e.preventDefault();drop.classList.add('drag');}));['dragleave','drop'].forEach(t=>drop.addEventListener(t,e=>{e.preventDefault();drop.classList.remove('drag');if(t==='drop'){if(e.dataTransfer.files.length!==1){toast('请一次导入一个矩阵文件。');return;}inputFile(e.dataTransfer.files[0]);}}));
function loadExample(){return inputFile(new File([SNPExamples.text],SNPExamples.filename,{type:'text/csv'}),true);}$('sample').onclick=loadExample;
function renderMatrix(){const m=dataState.matrix,q=dataState.qc;if(!m||!q)return;$('matrixPanel').classList.remove('hidden');$('matrixEmpty').classList.add('hidden');$('matrixSource').textContent=dataState.source.example?'合成示例矩阵':'用户导入矩阵';$('filename').textContent=dataState.source.name;$('fileInfo').textContent=`已导入 ${m.n} 样本 / ${m.m} SNP · 质控保留 ${q.keptSamples.length} / ${q.keptVariants.length}`;$('sampleCount').innerHTML=m.n.toLocaleString()+' <small>samples</small>';$('snpCount').innerHTML=m.m.toLocaleString()+' <small>variants</small>';$('sampleMeta').textContent=m.phenotypeAvailable?`病例 ${m.cases} / 对照 ${m.controls} · 保留 ${q.keptSamples.length}`:`未提供表型 · 保留 ${q.keptSamples.length}`;$('snpMeta').textContent=`原始缺失率 ${percent(m.missingRate)} · 保留 ${q.keptVariants.length}`;$('cvMeta').textContent=m.phenotypeAvailable?`分层 ${config.folds} 折 · 待接入训练`:'仅描述性质控 · 模型演示不可用';$('matrixSummary').innerHTML=[['原始样本 / SNP',`${m.n} / ${m.m}`],['原始缺失率',percent(m.missingRate)],['质控后样本 / SNP',`${q.keptSamples.length} / ${q.keptVariants.length}`],['质控后病例 / 对照',m.phenotypeAvailable?`${q.cases} / ${q.controls}`:'未提供表型']].map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('');const warnings=[...m.warnings];if(!q.keptSamples.length||!q.keptVariants.length)warnings.push('阈值过滤后无可用矩阵；可调整阈值或检查数据。');else if(m.phenotypeAvailable&&(!q.cases||!q.controls))warnings.push('质控后仅有一个表型类别，二分类流程不可运行。');else if(m.phenotypeAvailable&&Math.min(q.cases,q.controls)<config.folds)warnings.push(`少数类别不足 ${config.folds} 个样本；真实分层 ${config.folds} 折不可行，可降低折数或补充样本。`);warnings.push('MAF 基于同一计数等位基因的二倍体编码；请核对等位基因方向、参考基因组及样本顺序。');$('matrixWarnings').textContent=warnings.join(' ');const cols=m.variants.slice(0,8);$('matrixPreview').innerHTML='<thead><tr><th>sample_id</th>'+(m.phenotypeAvailable?'<th>phenotype（0/1）</th>':'')+cols.map(v=>`<th>${escapeHTML(v.id)}</th>`).join('')+'</tr></thead><tbody>'+m.samples.slice(0,8).map((s,i)=>`<tr><td>${escapeHTML(s.id)}</td>`+(m.phenotypeAvailable?`<td>${s.phenotype}</td>`:'')+cols.map((_,j)=>`<td>${Number.isNaN(m.values[i*m.m+j])?'NA':m.values[i*m.m+j]}</td>`).join('')+'</tr>').join('')+'</tbody>';$('exportFiltered').disabled=!q.keptSamples.length||!q.keptVariants.length;renderQC();}
function qcVisible(){const query=$('qcSearch').value.trim().toLowerCase(),filter=$('qcFilter').value;return(dataState.qc?.variants||[]).filter(v=>v.id.toLowerCase().includes(query)&&(filter==='all'||(filter==='pass'?v.pass:!v.pass)));}
function renderQC(){const rows=qcVisible(),pages=Math.max(1,Math.ceil(rows.length/25));dataState.page=Math.min(dataState.page,pages);$('qcRows').innerHTML=rows.slice((dataState.page-1)*25,dataState.page*25).map(v=>`<tr><td>${escapeHTML(v.id)}</td><td>${v.called}</td><td>${percent(v.missingRate)}</td><td>${numberText(v.countedAF)}</td><td>${numberText(v.maf)}</td><td>${v.pass?'通过':escapeHTML(v.reasons.join('；'))}</td></tr>`).join('')||'<tr><td colspan="6">没有匹配位点</td></tr>';$('qcPageInfo').textContent=`共 ${rows.length} 位点 · 第 ${dataState.page} / ${pages} 页`;$('qcPrev').disabled=dataState.page===1;$('qcNext').disabled=dataState.page===pages;}
$('qcSearch').oninput=()=>{dataState.page=1;renderQC();};$('qcFilter').onchange=()=>{dataState.page=1;renderQC();};$('qcPrev').onclick=()=>{dataState.page--;renderQC();};$('qcNext').onclick=()=>{dataState.page++;renderQC();};
function readConfig(){for(const id of ['maf','missing','sampleMissing','fdr'])if(!$(id).value||!$(id).checkValidity())throw Error('请填写有效的质控和 FDR 阈值。');const folds=+$('folds').value;if(!Number.isInteger(folds)||folds<2||folds>20)throw Error('交叉验证折数须为 2–20 的整数。');return{maf:+$('maf').value,missing:+$('missing').value,sampleMissing:+$('sampleMissing').value,fdr:+$('fdr').value,folds};}
$('save').onclick=async()=>{if(busy||dataState.pending){toast('请等待当前操作完成。');return;}let next,chosen;try{next=readConfig();chosen=new Set([...document.querySelectorAll('#configModels input:checked')].map(e=>e.value));if(!chosen.size)throw Error('请至少选择一个模型。');}catch(e){toast(e.message);return;}const job=startJob();setPending(true);try{const qc=dataState.matrix?await matrixTask('qc',{matrix:dataState.matrix,config:next},job.signal):null;if(!isCurrent(job))return;config=next;selected=chosen;if(qc){dataState.qc=qc;dataState.page=1;renderMatrix();}renderModels();renderRows();resetFlow();$('cvMeta').textContent=dataState.matrix?.phenotypeAvailable?`分层 ${config.folds} 折 · 待接入训练`:'模型训练待接入';window.ScientificPlots?.configure(config.folds,[...selected]);navigate('figures');toast('配置已保存：描述性质控已更新，科研图为独立合成数据演示。');}catch(e){if(isCurrent(job)&&e.name!=='AbortError')toast(e.message);}finally{if(isCurrent(job))setPending(false);}};
async function exportMatrix(filtered){const m=dataState.matrix,q=dataState.qc,source=dataState.source;if(!m||dataState.pending)return;const si=filtered?q.keptSamples:m.samples.map((_,i)=>i),vi=filtered?q.keptVariants:m.variants.map((_,i)=>i);if(!si.length||!vi.length){toast('没有可导出的矩阵。');return;}const rows=[[...(m.phenotypeAvailable?['sample_id','phenotype']:['sample_id']),...vi.map(j=>m.variants[j].id)]];for(let k=0;k<si.length;k++){const i=si[k];rows.push([m.ids[i],...(m.phenotypeAvailable?[m.y[i]]:[]),...vi.map(j=>m.values[i*m.m+j])]);if(k%250===0)await new Promise(r=>setTimeout(r,0));}download(filtered?(source.example?'SNP-DEMO-QC-filtered-matrix.csv':'SNP-QC-filtered-matrix.csv'):(source.example?'SNP-DEMO-normalized-matrix.csv':'SNP-normalized-matrix.csv'),SNPMatrix.csv(rows));toast('矩阵已导出；缺失值保留为 NA。');}
$('exportMatrix').onclick=()=>exportMatrix(false);$('exportFiltered').onclick=()=>exportMatrix(true);
$('exportSamples').onclick=()=>{if(!dataState.matrix||dataState.pending)return;const m=dataState.matrix,kept=new Set(dataState.qc.keptSamples);download('SNP-sample-QC.csv',SNPMatrix.csv([[...(m.phenotypeAvailable?['sample_id','phenotype']:['sample_id']),'original_missing_count','original_missing_rate','pass','reason'],...m.samples.map((s,i)=>[s.id,...(m.phenotypeAvailable?[s.phenotype]:[]),s.missing,s.missingRate,kept.has(i),kept.has(i)?'':'sample_missing_rate_above_threshold'])]));};
$('exportVariants').onclick=()=>{if(!dataState.qc||dataState.pending)return;download('SNP-variant-QC.csv',SNPMatrix.csv([['SNP','called_after_sample_filter','missing_rate','counted_AF','MAF','pass','reasons'],...dataState.qc.variants.map(v=>[v.id,v.called,v.missingRate,v.countedAF,v.maf,v.pass,v.reasons.join(';')])]));};
$('exportManifest').onclick=()=>{if(!dataState.matrix||dataState.pending)return;const m=dataState.matrix,q=dataState.qc,record={version:'0.4',exportedAt:new Date().toISOString(),source:dataState.source,encoding:m.options,inputHeader:m.inputHeader,delimiter:m.delimiter,config,selectedModels:[...selected],input:{samples:m.n,variants:m.m,phenotypeAvailable:m.phenotypeAvailable,cases:m.cases,controls:m.controls,missingRate:m.missingRate},qc:{samples:q.keptSamples.length,variants:q.keptVariants.length,cases:q.cases,controls:q.controls},method:'Sample missingness filtering followed by recomputed diploid counted allele frequency / MAF and variant missingness filtering; no imputation',modelResults:'SIMULATED; no model fitted',associationResults:'SIMULATED; no tests performed',privacy:'Browser-local, not uploaded or persisted',scientificFigures:window.ScientificPlots?.state.batch?window.ScientificPlots.record(window.ScientificPlots.state.batch,window.ScientificPlots.state.ordered):null},url=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='SNP-import-QC-record.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const demoRun=run;
run=async function(){if(dataState.pending)throw Error('请等待导入完成。');if(!dataState.matrix||!dataState.qc)throw Error('请先导入有效矩阵。');const q=dataState.qc;if(!dataState.matrix.phenotypeAvailable)throw Error('当前为仅描述性质控模式；映射完整的 0/1 或 1/2 表型列后才能运行二分类演示。');if(q.keptSamples.length<2||!q.keptVariants.length)throw Error('质控后没有足够样本或 SNP，请调整阈值。');if(!q.cases||!q.controls)throw Error('质控后只有一个表型类别，无法进入二分类演示流程。');$('save').disabled=true;try{const result=await demoRun();$('flowState').textContent='真实质控 / 模型演示完成';$('status').textContent=`真实质控保留 ${q.keptSamples.length} 样本 / ${q.keptVariants.length} SNP；训练、填补和关联检验仍为模拟。`;window.ScientificPlots?.configure(config.folds,[...selected]);return{...result,samples:q.keptSamples.length,variants:q.keptVariants.length,simulatedModels:true};}finally{setPending(false);}};
$('run').onclick=()=>run().catch(e=>toast(e.message));$('export').onclick=()=>{download('SNP-DEMO-candidates.csv',SNPMatrix.csv([['data_source','SNP','chr','position','p_simulated','q_simulated','importance_simulated','status'],...visibleHits().map(h=>['SIMULATED',h.id,h.chr,h.pos,h.p,h.q,h.importance,h.q<config.fdr?'candidate':'not_significant'])]));toast('已导出模拟位点结果，不是上传矩阵的关联检验。');};
